const TX_ACTIVITY_GROUP = "Texas classroom-teacher CPE activity type";
const NY_ACTIVITY_GROUP = "New York classroom-teacher CTLE activity type";
const PA_ACTIVITY_GROUP = "Pennsylvania Act 48 activity type";

function nyCategoryBindings(
  ruleSetId:
    | "ny-professional-classroom-teacher-standard-ctle-2026-v1"
    | "ny-professional-esol-bilingual-ctle-2026-v1",
  languageHours: 15 | 50,
): readonly CategorySeedBinding[] {
  const prefix =
    ruleSetId === "ny-professional-esol-bilingual-ctle-2026-v1"
      ? "ny-professional-esol-bilingual-ctle-2026"
      : "ny-professional-classroom-standard-ctle-2026";

  return [
    [
      `${prefix}-other-approved-ctle`,
      ruleSetId,
      "Other Approved CTLE",
      0,
      "informational",
      "independent",
      null,
      "always",
      "Use this activity-type classifier for approved content, pedagogy, language-acquisition, or other acceptable CTLE that is not claimed as one of the capped mentoring activity types.",
      NY_ACTIVITY_GROUP,
      0,
    ],
    [
      `${prefix}-mentor-new-teacher`,
      ruleSetId,
      "Mentoring a New Classroom Teacher",
      30,
      "maximum",
      "independent",
      null,
      "optional",
      "At the district or BOCES sponsor's discretion, at most 30 CTLE hours may count in a five-year period for mentoring a new classroom teacher in its mentoring program. The sponsor must approve the activity and issue CTLE documentation.",
      NY_ACTIVITY_GROUP,
      1,
    ],
    [
      `${prefix}-mentor-teacher-candidate`,
      ruleSetId,
      "Mentoring a Teacher Candidate",
      25,
      "maximum",
      "independent",
      null,
      "optional",
      "At the district or BOCES sponsor's discretion, at most 25 CTLE hours may count in a five-year period for mentoring a teacher candidate. The sponsor must approve the activity and issue CTLE documentation.",
      NY_ACTIVITY_GROUP,
      2,
    ],
    [
      `${prefix}-language-acquisition`,
      ruleSetId,
      "Language Acquisition Addressing English Language Learners",
      languageHours,
      "minimum",
      "overlapping",
      null,
      "always",
      `Complete at least ${languageHours} of the 100 CTLE hours in the applicable NYSED language-acquisition content. This no-waiver full-cycle variant must not be used when TEACH calculates a reduced language requirement.`,
      null,
      3,
    ],
  ];
}

